package challenge.leetcode.easy.climbingStairs;

import java.util.Arrays;
import lombok.extern.slf4j.Slf4j;
import org.apache.log4j.BasicConfigurator;

/**
 * @author Administrator
 * @Created 06/06/2025,
 * @Project 3C: Competitive Coding Challenges
 * @Problem 70
 * @Difficulty Easy
 * @Tags math,
 * dynamic programming,
 * memoization
 * @link <a href="https://leetcode.com/problems/climbing-stairs/">www.leetcode.com/70</a>
 * @Description You are climbing a staircase. It takes <code>n</code> steps to reach the top.<br>
 * Each time you can either climb <code>1</code> or <code>2</code> steps. In how many distinct ways can you climb to the top?
 *
 * <ul>
 * 		<li><b>Example 1:</b>
 * 			<br><b>Input:</b> {@code n = 2}
 * 			<br><b>Output:</b> {@code 2}
 * 			<br><b>Explanation:</b> There are 2 ways to climb to the top.
 * 				<br>1. 1+1 = 2
 * 				<br>2. 2 = 2
 * 		</li>
 * </ul>
 * <ul>
 * 		<li><b>Example 2:</b>
 * 			<br><b>Input:</b> {@code n = 3}
 * 			<br><b>Output:</b> {@code 3}
 * 			<br><b>Explanation:</b> There are 3 ways to climb to the top.
 * 				<br>1. 1 + 1 + 1 = 3
 * 				<br>2. 1 + 2 = 3
 * 				<br>2. 2 + 1 = 3
 * 		</li>
 * </ul>
 *
 * <p>
 * <b>Constraints:</b>
 * <ul>
 *     <li><code>1 &le; n &le; 45</code></li>
 * </ul>
 * </p>
 **/
@Slf4j
public class ClimbingStairs
{
	public static void main(String[] args)
	{
		BasicConfigurator.configure();

		int n = 19;
//		log.info("{} -> {}", n, climbStairs(n));
//		log.info("{} -> {}", 25, climbStairs(25));
	}

	/**
	 * <br><b>Solution scratchpad</b><br>
	 * <br><a href="https://excalidraw.com/#json=dI9oG8XbvJUqGxL0QFzrb,6Zni3HoirJeFC1UnQMiK_A">View scratchpad online</a>
	 * <br>
	 * <img src="data:image/jpeg;base64,"/>
	 */
	public static int climbStairs(int n)
	{
		// Naive Fibonacci solution
		// Base cases
		if (n < 3)
		{
			return n;
		}
		// integer overflow
		if (n > 45)
		{
			return -1;
		}

		int[] ints = new int[n + 1];
		ints[0] = 1;
		ints[1] = 2;

		for (int i = 2; i < ints.length - 1; i++)
		{
			ints[i] = ints[i - 1] + ints[i - 2];
		}
		System.out.println(Arrays.toString(ints));

		return ints[n - 1];
	}
}

